import json, pathlib
base=pathlib.Path('/workspace/variant_sources')
# rs: unique current RefSeq allele positions, NCBI SPDI 0-based -> 1-based
for fn in ['rs200533370_refsnp.json','rs241311_refsnp.json']:
    d=json.loads((base/fn).read_text())
    coords=sorted(set((m['allele_in_cur_release']['seq_id'], m['allele_in_cur_release']['position']+1) for m in d['present_obs_movements'] if 'allele_in_cur_release' in m))
    print(fn, coords)
# ClinVar start fields are displayed 1-based GRCh38 positions
for fn in ['NM_006492.3_c.595-2A-T_clinvar_4642.json','VCV000587372.6_clinvar_587372.json','OMIM_616787.0001_clinvar_224333.json']:
    d=json.loads((base/fn).read_text()); uid=d['result']['uids'][0]; rec=d['result'][uid]
    coords=[]
    for v in rec['variation_set']:
        for loc in v['variation_loc']:
            if loc['status']=='current' and loc['assembly_name']=='GRCh38': coords.append((loc['chr'], loc['start'], v.get('canonical_spdi')))
    print(fn, coords)
# ClinGen coordinates: start 0-based, end 1-based, hgvs confirms 1-based
fn='CA548798891_clingen.json'; d=json.loads((base/fn).read_text())
coords=[]
for ga in d['genomicAlleles']:
    if ga.get('referenceGenome')=='GRCh38':
        coords.append((ga.get('chromosome'), ga['coordinates'], ga.get('hgvs')))
print(fn, coords)
PY"
